ValidationRule.errorConditionFormula:
AND(
    /* Bypass validation for authorized rollback users */
    NOT($Permission.Zeta_Rollback_Lottery),

    TEXT(PRIORVALUE(Status)) = "Submitted",

    /* Only validate when the value is actually changing */
    TEXT(Status) <> TEXT(PRIORVALUE(Status)),

    NOT(
        OR(
            /* Always allowed */
            ISPICKVAL(Status, "Withdrawn/Declined"),

            /* Pre-Lottery allowed transition */
            AND(NOT(Has_Lottery_Run__c), ISPICKVAL(Status, "Eligible")),

            /* Post-Lottery allowed transition */
            AND(Has_Lottery_Run__c, ISPICKVAL(Status, "Waitlisted"))
        )
    )
)
